racking_pick_date::date = \'2025-01-17\' THEN \'MISSING_SHIPMENT_LOST\' WHEN Lower(tracking_sub_status) like \'%lost%\' or Lower(tracking_sub_status) like \'%damage%\' or Lower(tracking_sub_status) like \'%short%\' THEN \'EXCEPTION_LOST_DAMAGE\' WHEN STI_SKU is not null THEN \'INWARDED\' WHEN logistics_delivery_timestamp is not null THEN \'INWARD_PENDING\' WHEN tracking_pick_date is not null THEN \'DELIVERY_PENDING\' WHEN logistics_created_timestamp is not null then \'PICKUP_PENDING\' WHEN to_party is not null THEN \'ESHIP_PENDING\' WHEN to_party is null THEN \'WH_PENDING\' ELSE null END AS DUMMY_STATUS, qty - sti_qty as ex_short FROM UC u LEFT JOIN awb_find awb ON u.order_name = UPPER(TRIM(awb.find1)) LEFT JOIN sto ON CONCAT(UPPER(TRIM(u.order_name)), UPPER(TRIM(u.SKU))) = CONCAT(UPPER(TRIM(sto.order_no)), UPPER(TRIM(sto.sto_sku))) LEFT JOIN eship ON UPPER(TRIM(awb.find2)) = UPPER(TRIM(eship.unique_order_id)) LEFT JOIN sti ON CONCAT(UPPER(TRIM(sto_bill_no)), UPPER(TRIM(u.SKU))) = CONCAT(UPPER(TRIM(sti.bill_no)),UPPER(TRIM(sti.sti_sku))) WHERE (ifnull(FINAL_STORE,\'\') LIKE \'%FOCO%\' or ifnull(FINAL_STORE,\'\') LIKE \'%FOFO%\') ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.B2B_JOURNEY AS with data as ( ( select * from SNITCH_DB.MAPLEMONK.OWN_B2B_JOURNEY UNION ALL select * from SNITCH_DB.MAPLEMONK.FRANCH_B2B_JOURNEY ) ), new as ( select distinct order_name as identity1 ,order_type as type from snitch_db.maplemonk.warehouse_sla_performance where marketplace_mapped = \'STORE\' and order_date >= current_date - 120 ), draft1 as ( select type ,d.* from data d left join new n on TRIM(d.order_name) = trim(n.identity1) ) ,status as (select distinct order_name, final_status from SNITCH_DB.MAPLEMONK.checker_store_status ) , final as ( select d.*, s.final_status, CASE WHEN final_status = \'WH_PENDING\' THEN timestampdiff(day,order_date,current_date) WHEN final_status = \'ESHIP_PENDING\' THEN timestampdiff(day,sto_bill_date,current_date) WHEN final_status = \'PICKUP_PENDING\' THEN timestampdiff(day,logistics_created_timestamp,current_date) WHEN final_status = \'DELIVERY_PENDING\' THEN timestampdiff(day,logistics_expected_delivery_date,current_date) WHEN final_status = \'INWARD_PENDING\' THEN timestampdiff(day,logistics_delivery_timestamp,current_date) ELSE NULL END AS STATUS_AGEING from draft1 d left join status s on d.order_name = s.order_name ) select * from final where NOT(IFNULL(order_name,\'\') in (\'LAJPAT2743\',\'BTLORDER\',\'SO01233\',\'TRIONV2927\',\'CITADE3011\',\'BRIGAD3034\',\'RAJAHM2956\',\'VAPIGA3328\',\'VAPIGA3316\',\'VAPIGA3315\',\'VAPIGA3304\',\'VAPIGA3303\',\'VAPIGA3302\',\'VAPIGA3301\',\'VAPIGA3300\',\'VAPIGA3299\',\'VAPIGA3298\',\'VAPIGA3297\',\'SECTOR3245\',\'SECTOR3244\',\'LANDMA3247\',\'TRIONV3225\',\'SECTOR3246\',\'SECTOR3239\',\'SECTOR3257\',\'BRIGAD3388\',\'SECTOR3238\',\'SECTOR3256\',\'SECTOR3241\',\'BRIGAD3369\',\'MALADI3310\',\'MALADI3307\',\'SECTOR3242\',\'SECTOR3260\',\'SECTOR3259\',\'SECTOR3255\',\'BRIGAD3385\',\'ELPROM3325\',\'SECTOR3243\',\'SECTOR3258\',\'SECTOR3240\',\'XPERIA3270\',\'SECTOR3254\',\'HRBRLA3332\',\'ELPROM3510\',\'KALIDA4595\',\'KALIDA4309\',\'KALIDA4596\',\'KALIDA4311\',\'KALIDA4315\',\'KALIDA4312\',\'KALIDA4320\',\'KALIDA4322\',\'KALIDA4308\',\'KALIDA4319\',\'KALIDA4305\',\'KALIDA4314\',\'KALIDA4317\',\'KALIDA4321\',\'KALIDA4594\',\'KALIDA4306\',\'KALIDA4318\',\'KALIDA4316\',\'KALIDA4307\',\'KALIDA4310\',\'KALIDA4313\')) and NOT(IFNULL(order_name,\'\') like \'%HSRSALE%\') and NOT(IFNULL(order_name,\'\') like \'%QC-%\') and not(IFNULL(type,\'\') like \'%NSO%\') ;",
